import { getWorkspace } from '@schematics/angular/utility/workspace';
import { Rule, chain, SchematicContext, Tree } from '@angular-devkit/schematics';
import { NodePackageInstallTask } from '@angular-devkit/schematics/tasks';
import {
  addPackageJsonDependency,
  NodeDependencyType,
} from '@schematics/angular/utility/dependencies';
import { GenerateIconSubsetOptions } from './schema';

const SCRIPT_TEMPLATE = `
// scripts/collect-icons.mjs — generated by ngx-iconify-stack
// Scans templates for <ngx-icon icon="set:name"> and builds an offline subset.
// Runs in prebuild so the subset stays in sync with actual icon usage.
import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';

const ROOT = resolve(import.meta.dirname, '..');
const SRC = resolve(ROOT, 'src');
const OUT_FILE = resolve(SRC, 'generated', 'icon-subset.ts');

// ── scan: extract all "prefix:name" references from source files ──
function scanIcons(dir) {
  const pattern = /(?:icon|icons)\\s*=\\s*["']([\\w-]+:[\\w-]+)["']/g;
  const found = new Map(); // prefix → Set<name>

  function walk(path) {
    let entries;
    try { entries = readdirSync(path, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      const full = resolve(path, entry.name);
      if (entry.isDirectory() && !entry.name.startsWith('.') && entry.name !== 'node_modules') {
        walk(full);
      } else if (entry.isFile() && /\\.(html|ts)$/.test(entry.name)) {
        const content = readFileSync(full, 'utf8');
        let match;
        while ((match = pattern.exec(content)) !== null) {
          const [_, ref] = match;
          const sep = ref.indexOf(':');
          if (sep === -1) continue;
          const prefix = ref.slice(0, sep);
          const name = ref.slice(sep + 1);
          if (!found.has(prefix)) found.set(prefix, new Set());
          found.get(prefix).add(name);
        }
      }
    }
  }

  walk(dir);
  return found;
}

// ── subset: build IconifyJSON with only the used icons ──
function buildSubset(found) {
  const collections = [];

  for (const [prefix, names] of found) {
    const pkgPath = resolve(ROOT, \`node_modules/@iconify-json/\${prefix}/icons.json\`);
    if (!existsSync(pkgPath)) {
      console.warn(\`  ⚠ Set "\${prefix}" not found — install @iconify-json/\${prefix}\`);
      continue;
    }

    const fullSet = JSON.parse(readFileSync(pkgPath, 'utf8'));
    const subset = {
      prefix,
      icons: {},
      width: fullSet.width ?? 24,
      height: fullSet.height ?? 24,
    };

    let count = 0;
    for (const name of names) {
      if (fullSet.icons[name]) {
        subset.icons[name] = fullSet.icons[name];
        count++;
      } else {
        // Try alias chain
        let resolved = name;
        let depth = 0;
        while (fullSet.aliases?.[resolved]?.parent && depth < 10) {
          resolved = fullSet.aliases[resolved].parent;
          depth++;
        }
        if (fullSet.icons[resolved]) {
          subset.icons[name] = fullSet.icons[resolved];
          count++;
        } else {
          console.warn(\`  ⚠ Icon "\${prefix}:\${name}" not found in set\`);
        }
      }
    }

    collections.push(subset);
    console.log(\`  ✓ \${prefix}: \${count} icons\`);
  }

  return collections;
}

// ── main ──
console.log('🔍 Scanning icons...');
const found = scanIcons(SRC);

if (found.size === 0) {
  console.log('  No icons found in templates.');
  writeFileSync(OUT_FILE, '// No icons found — empty subset\\nexport const iconSubset = [];\\n', 'utf8');
  process.exit(0);
}

for (const [prefix, names] of found) {
  console.log(\`  \${prefix}: \${names.size} references\`);
}

console.log('\\n📦 Building subset...');
const collections = buildSubset(found);

const outDir = dirname(OUT_FILE);
if (!existsSync(outDir)) mkdirSync(outDir, { recursive: true });

writeFileSync(
  OUT_FILE,
  \`// Auto-generated by collect-icons.mjs — do not edit manually\\nimport type { IconifyJSON } from '@iconify/types';\\n\\nexport const iconSubset: IconifyJSON[] = \${JSON.stringify(collections, null, 2)};\\n\`,
  'utf8',
);

console.log(\`\\n✅ Subset written to \${OUT_FILE}\`);
`;

export function generateIconSubset(options: GenerateIconSubsetOptions): Rule {
  return async (tree: Tree, context: SchematicContext) => {
    const workspace = await getWorkspace(tree);
    const projectName = options.project ?? [...workspace.projects.keys()][0];
    const project = workspace.projects.get(projectName);
    const sourceRoot = project?.sourceRoot ?? 'src';

    // ── 1. Create the collect-icons script ──
    const scriptPath = 'scripts/collect-icons.mjs';
    if (tree.exists(scriptPath)) {
      context.logger.info('scripts/collect-icons.mjs already exists, skipping...');
    } else {
      tree.create(scriptPath, SCRIPT_TEMPLATE.trimStart());
      context.logger.info('✓ Created scripts/collect-icons.mjs');
    }

    // ── 2. Install @iconify-json/* for sets found during scan ──
    // (first run will warn about missing sets; subsequent builds self-heal)

    // ── 3. Add prebuild script ──
    const pkgPath = '/package.json';
    if (tree.exists(pkgPath)) {
      const pkg = JSON.parse(tree.read(pkgPath)!.toString());
      pkg.scripts ??= {};
      const existing = pkg.scripts.prebuild || '';
      if (!existing.includes('collect-icons')) {
        const prefix = existing ? existing + ' && ' : '';
        pkg.scripts.prebuild = prefix + 'node scripts/collect-icons.mjs';
        tree.overwrite(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
        context.logger.info('✓ Added prebuild hook: node scripts/collect-icons.mjs');
      } else {
        context.logger.info('prebuild already includes collect-icons, skipping...');
      }
    }

    // ── 4. Schedule npm install ──
    context.addTask(new NodePackageInstallTask());

    // ── 5. Update app.config.ts to import subset ──
    const appConfigPath = `${sourceRoot}/app/app.config.ts`.replace(/^\//, '');
    const generatedImport = `import { iconSubset } from '../generated/icon-subset';`;
    const providerCall = 'provideIconify({ offlineCollections: iconSubset })';

    if (tree.exists(appConfigPath)) {
      const content = tree.read(appConfigPath)!.toString();

      // Add import if not present
      if (!content.includes("'../generated/icon-subset'")) {
        // Find last import line
        const lines = content.split('\n');
        let lastImportIdx = -1;
        for (let i = 0; i < lines.length; i++) {
          if (/^import\s/.test(lines[i])) lastImportIdx = i;
        }
        if (lastImportIdx >= 0) {
          lines.splice(lastImportIdx + 1, 0, generatedImport);
          tree.overwrite(appConfigPath, lines.join('\n'));
        }
      }

      // Replace bare provideIconify() with offlineCollections version
      const updated = tree.read(appConfigPath)!.toString();
      if (updated.includes('provideIconify()')) {
        tree.overwrite(appConfigPath, updated.replace('provideIconify()', providerCall));
      } else if (!updated.includes('offlineCollections')) {
        // Find provideIconify call without args and update it
        tree.overwrite(
          appConfigPath,
          updated.replace(/provideIconify\(\)/g, providerCall),
        );
      }

      context.logger.info(`✓ Updated ${appConfigPath} with offlineCollections`);
    } else {
      context.logger.warn(
        `⚠ ${appConfigPath} not found. Add this manually:\n` +
          `  ${generatedImport}\n` +
          `  provideIconify({ offlineCollections: iconSubset })`,
      );
    }
  };
}
